# ============================================================================
# Modulo OPERACIONES + rol "operaciones"
# ============================================================================
# - Menu Operaciones con dos opciones: Atencion a Socios (baja de socio, baja de invitado)
#   y Atencion a Autoridades (citatorios PROFECO, solicitudes de Fiscalias / MP).
# - Rol nuevo "Operaciones": solo puede usar este modulo (el backend bloquea todo lo demas).
# - Juridico, Cabeza de Juridico y super_admin ven todas las solicitudes, cambian el estatus
#   y reciben un correo por cada solicitud nueva.
#
# Como usarlo:
#   1) Corre este script desde la RAIZ del repo (Contratos) en PowerShell.
#   2) git add -A ; git commit -m "Modulo Operaciones" ; git push
#   3) Con la DATABASE_URL de produccion en backend\.env:
#        cd backend
#        npm run migrate:operaciones
#      (crea el rol y las tablas; se puede correr mas de una vez). Borra el .env al terminar.
#   4) En Administracion > Usuarios, crea/edita usuarios con el rol "Operaciones".
# ============================================================================

function Write-FileFromBase64 {
    param([string]$RelativePath, [string]$Base64Content)
    $fullPath = Join-Path (Get-Location) $RelativePath
    $dir = Split-Path $fullPath -Parent
    if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
    [System.IO.File]::WriteAllBytes($fullPath, [System.Convert]::FromBase64String($Base64Content))
    Write-Host "Escrito: $RelativePath"
}

if (-not (Test-Path (Join-Path (Get-Location) "backend/package.json"))) {
    Write-Host "Corre este script desde la raiz del repo (la carpeta que contiene backend y frontend)." -ForegroundColor Red
    exit 1
}

